values
(1, 'Básico', 'Quantas gramas de alface colocamos no BigMac?', '12 gr na base e 12 gr no clube, totalizando 24 gramas.', array['14 gr na base e 14 gr no clube, totalizando 28 gramas.', '10 gr na base e 10 gr no clube, totalizando 20 gramas.', '15 gr na base e 15 gr no clube, totalizando 30 gramas.']::text[]),
