(10, 'Básico', 'Quais são os EPIs necessários para atuar na estação de chapa?', 'Avental e mangote.', array['Avental, luva de malha e óculos.', 'Mangote, luva térmica azul e touca.', 'Avental antichamas e bota de borracha.']::text[]),
(11, 'Básico', 'Cite bons padrões de higiene essenciais para o trabalho no McDonald''s.', 'Cabelos presos, unhas curtas, sem esmalte e limpas, barba feita, sem adornos e com redinha.', array['Cabelos presos, unhas com base incolor, barba aparada, relógio discreto e redinha.', 'Cabelos presos, unhas curtas, uso permitido apenas de aliança lisa e barba feita.', 'Cabelos com boné sem redinha, unhas curtas, sem esmalte e brinco pequeno.']::text[]),
(12, 'Básico', 'Qual a compressão do pão e tempo de tostagem da tostadeira?', 'Compressão 4, tempo de tostagem 22 segundos.', array['Compressão 3, tempo de tostagem 18 segundos.', 'Compressão 4, tempo de tostagem 17 segundos.', 'Compressão 5, tempo de tostagem 25 segundos.']::text[]),
(13, 'Básico', 'Qual a temperatura das UHCs de carnes vermelhas e brancas respectivamente?', 'Carnes vermelhas 79°C e carnes brancas 85°C.', array['Carnes vermelhas 85°C e carnes brancas 79°C.', 'Carnes vermelhas 74°C e carnes brancas 82°C.', 'Carnes vermelhas 77°C e carnes brancas 90°C.']::text[]),
