(19, 'Básico', 'A partir de quantos sanduíches produzidos na hora devemos abrir o lado 2?', '125 sanduíches na hora.', array['100 sanduíches na hora.', '150 sanduíches na hora.', '90 sanduíches na hora.']::text[]),
(20, 'Básico', 'Em qual direção devem ficar a base e a coroa dos pães na linha?', 'Base sentido UHC e Coroa sentido tostadeira.', array['Base sentido tostadeira e Coroa sentido UHC.', 'Base e Coroa sentido tostadeira.', 'Base e Coroa sentido UHC.']::text[]),
