(26, 'Básico', 'Em quantos pedaços devemos cortar a carne de Crispy da Salada Mix?', 'De 5 a 7 pedaços.', array['De 4 a 6 pedaços.', 'De 6 a 8 pedaços.', 'Em 4 pedaços iguais.']::text[]),
