(99, 'Básico', 'Qual o primeiro passo para fazer o McShake?', 'Colocar 15 ml de leite no fundo do copo.', array['Colocar 1 oz de cobertura no fundo do copo.', 'Extrair a base de baunilha até a linha do copo.', 'Colocar 30 ml de mix no fundo do copo.']::text[]),
(100, 'Básico', 'De que forma identificamos as bebidas zero?', 'Colocando a letra Z com caneta no copo.', array['Colocando dois canudos na tampa do copo.', 'Dobrar todas as bolinhas da tampa plástica.', 'Colocando um adesivo vermelho na lateral do copo.']::text[]),
(101, 'Básico', 'Qual o tamanho da casquinha?', '3,5 voltas ou 7,5 cm.', array['4,5 voltas ou 8,5 cm.', '3 voltas ou 6,5 cm.', '5 voltas ou 9 cm.']::text[]),
(102, 'Básico', 'Qual o 5º item que podemos sugerir para complementar a refeição do cliente?', 'O café.', array['O queijo extra.', 'A McFritas Grande.', 'O brinquedo do McLanche Feliz.']::text[]),
(103, 'Básico', 'Qual o tempo de vida do café coado?', '1 hora.', array['2 horas.', '30 minutos.', '45 minutos.']::text[]),
(104, 'Básico', 'Quais são as 5 estações principais do Drive-Thru?', 'Face (COD), Caixa Drive, Apoio, Entrega e Conferente.', array['Iniciador, Condimentador, Finalizador, Runner e Caixa.', 'Face (COD), Totem, Balcão, Runner e Motoboy.', 'Caixa Drive, Bebidas, Fritadeira, Chapa e Estoque.']::text[]),
(105, 'Básico', 'Qual o objetivo de imprecisão do delivery dos restaurantes?', '1%.', array['2%.', '0,5%.', '3%.']::text[]),
(106, 'Básico', 'A partir de quantas bebidas usamos suporte no drive?', 'A partir de 2 bebidas.', array['A partir de 1 bebida.', 'A partir de 3 bebidas.', 'A partir de 4 bebidas.']::text[]),
(107, 'Básico', 'O que é sistema PEPS?', 'Primeiro que entra, primeiro que sai.', array['Primeiro que estoca, primeiro que serve.', 'Produto embalado, produto sanitizado.', 'Preparo especial para sanduíches.']::text[]),
(108, 'Intermediário', 'Qual a temperatura da mesa de condimentação?', 'De 49 a 57°C.', array['De 40 a 48°C.', 'De 57 a 63°C.', 'De 46 a 52°C.']::text[]),
(109, 'Intermediário', 'Qual o empilhamento máximo dos pães?', 'Big Mac 26 bandejas, demais 20 bandejas.', array['Big Mac 20 bandejas, demais 26 bandejas.', 'Big Mac 24 bandejas, demais 18 bandejas.', 'Todos os pães no máximo 22 bandejas.']::text[]),
(110, 'Intermediário', 'Qual sabonete usamos para lavar as mãos?', 'Sabonete Bactericida.', array['Detergente Neutro Concentrado.', 'Sabonete Líquido Comum.', 'Desengordurante Peróxido.']::text[]),
(111, 'Intermediário', 'Onde encontramos informações sobre alérgenos alimentares?', 'Na lâmina de bandeja, Saber ou site do McDonald''s.', array['Apenas no manual impresso da gerência.', 'Somente nas caixas na câmara fria.', 'No monitor KVS da linha e no pirômetro.']::text[]),
(112, 'Intermediário', 'Qual o zoom correto para o KVS da linha?', '4X2.', array['3X3.', '2X2.', '4X4.']::text[]),
(113, 'Intermediário', 'Quais as primeiras estações que devemos posicionar na cozinha?', 'Chapa e LOPE.', array['Iniciador e Finalizador.', 'McFritas e Produtos Fritos.', 'Condimentação e Bebidas.']::text[]),
(114, 'Intermediário', 'Em qual momento o iniciador aperta servido no pedido da linha, quando trabalhamos com 2 pessoas?', 'Após dar os dois primeiros condimentos ou assim que a pessoa da condimentação assumir.', array['Assim que o pão entra na tostadeira vertical.', 'Somente depois que o sanduíche é embrulhado na OAT.', 'Antes de colocar os pães para caramelizar.']::text[]),
(115, 'Intermediário', 'Qual a condimentação correta da Salada Mix?', '120 g de alface, 4 tomates cereja, 14 g de cebola shoyu, 4 picles, 16 g de bacon triturado e uma carne.', array['100 g de alface, 2 tomates, 7 g de cebola fresca, 2 picles, 2 fatias de bacon e uma carne.', '150 g de alface, 6 tomates cereja, 20 g de cebola shoyu, 2 picles, 10 g de bacon e uma carne.', '120 g de alface, 4 tomates cereja, 14 g de cebola crispy, 2 picles, 16 g de queijo e uma carne.']::text[]),
(116, 'Intermediário', 'Qual o tempo de vida primária do tomate?', 'Produtos hortifruti in natura não têm tempo de validade.', array['10 dias, incluindo a data de fabricação.', '7 dias sob refrigeração na Walk-in.', '5 dias a partir do recebimento na loja.']::text[]),
(117, 'Intermediário', 'Quantos panos devemos ter na área de chapa e para que servem?', '4 panos: 2 para utensílios, 1 para área gordurosa, 1 para áreas não gordurosas.', array['3 panos: 1 para tostadeira, 1 para mesa e 1 para UHC.', '4 panos: 1 para utensílios, 2 para área gordurosa e 1 para o chão.', '2 panos: 1 para utensílios e 1 para limpar a chapa.']::text[]),
(118, 'Intermediário', 'Qual o tempo de remoção das carnes?', '18 segundos.', array['15 segundos.', '22 segundos.', '12 segundos.']::text[]),
(119, 'Intermediário', 'Qual o tempo de vida secundário do bacon cru?', '5 dias, incluindo o tempo de descongelamento de 12 horas.', array['4 dias, incluindo 24 horas de descongelamento.', '7 dias, incluindo 12 horas de descongelamento.', '3 dias, incluindo 6 horas de descongelamento.']::text[]),
(120, 'Intermediário', 'Qual o tempo de vida da mostarda depois de aberta?', '7 dias sob refrigeração.', array['5 dias sob refrigeração.', '24 horas sob refrigeração.', '10 dias sob refrigeração.']::text[]),
(121, 'Intermediário', 'Qual o tempo de vida do picles após aberto?', '3 dias sob refrigeração (com salmoura). Sem salmoura 24 horas.', array['7 dias com salmoura e 48 horas sem salmoura.', '5 dias com salmoura e 12 horas sem salmoura.', '48 horas com salmoura e 4 horas sem salmoura.']::text[]),
(122, 'Intermediário', 'Qual o tempo de vida primário da cebola e alface?', '10 dias, incluindo a data de fabricação.', array['7 dias, incluindo a data de fabricação.', '15 dias a partir da entrega.', '5 dias sob refrigeração na Walk-in.']::text[]),
(123, 'Intermediário', 'Qual o percentual máximo de compostos polares aceitável para a gordura?', '24%.', array['20%.', '18%.', '30%.']::text[]),
(124, 'Intermediário', 'Quais os sinais de decomposição do óleo?', 'Espuma Amarelada, Cheiro Forte e ácido, Cor escura e Fumaça excessiva.', array['Óleo muito claro, ausência de bolhas e sem cheiro.', 'Espuma branca leve, cor dourada brilhante e aroma suave.', 'Cristalização nas bordas da cuba e fervura abaixo de 100°C.']::text[]),
(125, 'Intermediário', 'Quais são os 6 inimigos do óleo?', 'Sal, Ar, Água, Altas temperaturas, Resíduos de carbono e Detergente.', array['Sal, Açúcar, Gelo, Baixas temperaturas, Luz solar e Papel.', 'Ar, Água, Cloro, Óleo novo, Batata congelada e Inox.', 'Sal, Pimenta, Cebola, Vapor, Fritura rápida e Filtragem.']::text[]),
(126, 'Intermediário', 'Qual o tempo de vida do queijo na mesa de preparação?', '4 horas, incluindo 2 horas de ambientação.', array['6 horas, incluindo 2 horas de ambientação.', '2 horas no total, sendo 1 hora de ambientação.', '8 horas, incluindo 4 horas de ambientação.']::text[]),
(127, 'Intermediário', 'Qual a quantidade de água que devemos usar para hidratar 1 pacote de cebola?', '3 litros, de 1 a 4°C.', array['4 litros, de 1 a 7°C.', '2 litros, de 5 a 10°C.', '3,5 litros, em temperatura ambiente.']::text[]),
(128, 'Intermediário', 'Quantas fatias de queijo podemos colocar em cada espaço da cuba de ambientação para queijos?', '1 bloco, 40 fatias, dividido em 2 partes.', array['2 blocos, 80 fatias, divididos em 4 partes.', 'Meio bloco, 20 fatias, sem dividir.', '1 bloco, 60 fatias, dividido em 3 partes.']::text[]),
(129, 'Intermediário', 'A que altura devemos segurar o saleiro das McFritas?', '20 cm.', array['10 cm.', '30 cm.', '5 cm.']::text[]),
(130, 'Intermediário', 'De que forma devemos segurar as pistolas de molho ao condimentar os sanduíches?', 'Com as duas mãos a 2 cm de altura.', array['Com apenas uma mão a 10 cm de altura.', 'Com as duas mãos a 15 cm de altura.', 'Encostando o bico diretamente no pão.']::text[]),
(131, 'Intermediário', 'Qual o peso das McFritas P, M e G?', '73 g, 102 g e 146 g, respectivamente.', array['43 g, 102 g e 146 g, respectivamente.', '70 g, 100 g e 150 g, respectivamente.', '75 g, 110 g e 140 g, respectivamente.']::text[]),
(132, 'Intermediário', 'Quantas vezes devemos misturar as McFritas após salgá-las?', 'De 2 a 3 vezes para misturar o sal por igual.', array['Apenas 1 vez para não quebrar.', 'De 5 a 6 vezes vigorosamente.', 'Não devemos misturar após salgar.']::text[]),
(133, 'Intermediário', 'Qual a temperatura e tempo de aquecimento das chapas?', 'Platen Superior 218°C / Inferior 177°C - Aquecimento 45 minutos.', array['Platen Superior 177°C / Inferior 218°C - Aquecimento 30 minutos.', 'Platen Superior 254°C / Inferior 271°C - Aquecimento 45 minutos.', 'Platen Superior 200°C / Inferior 168°C - Aquecimento 20 minutos.']::text[]),
(134, 'Intermediário', 'Qual a temperatura e tempo de congelamento dos congeladores portáteis?', 'De -18 a -23°C e 45 minutos de congelamento.', array['De -10 a -15°C e 30 minutos de congelamento.', 'De 1 a 4°C e 45 minutos de resfriamento.', 'De -18 a -23°C e 15 minutos de congelamento.']::text[]),
(135, 'Intermediário', 'Onde devem ser descartados os rejeitos?', 'Lixeira identificada com etiqueta e saco preto.', array['Qualquer lixeira do salão com saco transparente.', 'Lixeira comum da linha com saco azul.', 'Direto nas caixas de papelão da câmara.']::text[]),
(136, 'Intermediário', 'Quais os princípios da Cooltura de Serviço?', 'Agilidade, Generosidade, Humildade, Vocação de Serviço e Inclusão.', array['Limpeza, Organização, Preparação, Estocagem e Rapidez.', 'Qualidade, Serviço, Limpeza, Valor e Sustentabilidade.', 'Simpatia, Velocidade, Precisão, Economia e Liderança.']::text[]),
(137, 'Intermediário', 'Qual o propósito da Marca?', 'Fazer de cada dia uma oportunidade de alimentar pessoas e construir sonhos.', array['Servir comida rápida e barata em todos os bairros.', 'Ser a maior rede de hambúrgueres do mundo.', 'Vender mais combos grandes e adicionais todos os dias.']::text[]),
(138, 'Intermediário', 'Qual a declaração de identidade da Marca?', 'Fazemos as coisas simples, juntos e com paixão.', array['Pequenas mudanças, grande impacto no sabor.', 'Primeiro que entra, primeiro que sai sempre.', 'Olha, serve e ativa com velocidade máxima.']::text[]),
(139, 'Intermediário', 'Com quanto tempo de antecedência deve ser feito o plano de chão?', '48 horas.', array['24 horas.', '12 horas.', '72 horas.']::text[]),
(140, 'Intermediário', 'Qual é a promessa do fazer?', 'Fazer bem, fazer rápido e fazer especial.', array['Fazer limpo, fazer quente e fazer barato.', 'Olhar, servir e ativar no tempo certo.', 'Limpar, lavar, enxaguar e sanitizar.']::text[]),
(141, 'Intermediário', 'Qual a condimentação e quantidades de ingredientes do Quarteirão?', '1/40 oz de mostarda, 1/2 oz de ketchup, 7 g de cebola fresca, 2 picles, 2 fatias de queijo em estrela, 1 carne 4:1.', array['1/40 oz de mostarda, 1/3 oz de ketchup, 3,5 g de cebola hidratada, 1 picles, 1 queijo, 1 carne 4:1.', '1/2 oz de mostarda, 1/2 oz de ketchup, 10 g de cebola fresca, 3 picles, 2 queijos, 1 carne 10:1.', '1/40 oz de mostarda, 1/2 oz de ketchup, 28 g de alface, 2 tomates, 2 queijos, 1 carne 4:1.']::text[]),
(142, 'Intermediário', 'Qual a condimentação e quantidades de ingredientes do Cheeseburger?', '1/40 oz de mostarda, 1/3 oz de ketchup, 1 picles, 1 fatia de queijo, 1 carne de 10:1 com 3,5 g de cebola.', array['1/40 oz de mostarda, 1/3 oz de ketchup, 2 picles, 2 queijos, 1 carne 10:1 com 7 g de cebola.', '1/3 oz de mostarda, 1/3 oz de ketchup, 2 picles, 1 queijo, 1 carne 4:1 com 3,5 g de cebola.', '1/40 oz de mostarda, 1/3 oz de ketchup, 12 g de alface, 1 picles, 1 queijo e 1 carne 10:1.']::text[]),
(143, 'Intermediário', 'Qual a condimentação e quantidades de ingredientes do McNífico Bacon?', '1/40 oz mostarda, 1/2 oz ketchup, 7 g cebola fresca, 2/3 oz maionese, 28 g alface, 2 tomates, 2 bacons, 1 queijo, 1 carne 4:1.', array['1/40 oz mostarda, 1/3 oz ketchup, 3,5 g cebola, 1/2 oz maionese, 12 g alface, 1 tomate, 3 bacons, 2 queijos, 1 carne 4:1.', '1 oz molho tasty, 1/2 oz ketchup, 10 g cebola, 28 g alface, 2 tomates, 2 bacons, 3 queijos ementhal, 1 carne 4:1.', '1/40 oz mostarda, 1/2 oz ketchup, 7 g cebola, 2/3 oz maionese, 24 g alface, 1 tomate, 1 bacon, 2 queijos, 1 carne 10:1.']::text[]),
(144, 'Intermediário', 'Qual o distanciamento e espaçamento que devemos manter entre as caixas nas câmaras?', '5 cm do chão e das paredes e 2,5 cm entre as caixas.', array['10 cm do chão e das paredes e 5 cm entre as caixas.', '3 cm do chão e das paredes e 1 cm entre as caixas.', '8 cm do chão e das paredes e 4 cm entre as caixas.']::text[]),
(145, 'Intermediário', 'Qual o empilhamento máximo para as caixas de batata?', '6 caixas.', array['4 caixas.', '5 caixas.', '8 caixas.']::text[]),
(146, 'Intermediário', 'Qual o empilhamento máximo para as caixas de alface?', '6 caixas.', array['4 caixas.', '5 caixas.', '8 caixas.']::text[]),
(147, 'Intermediário', 'Qual o empilhamento máximo para as caixas de mix?', '4 caixas.', array['6 caixas.', '5 caixas.', '3 caixas.']::text[]),
(148, 'Intermediário', 'Qual o empilhamento máximo para caixas de suco?', '4 caixas.', array['6 caixas.', '5 caixas.', '8 caixas.']::text[]),
(149, 'Intermediário', 'Qual o empilhamento máximo para caixas de queijo?', '5 caixas.', array['4 caixas.', '6 caixas.', '8 caixas.']::text[]),
(150, 'Intermediário', 'O que significa a sigla LOPE?', 'Limpeza, Organização, Preparação e Estocagem.', array['Lavagem, Operação, Produção e Entrega.', 'Linha Operacional de Produtos e Embalagens.', 'Limpeza, Operação, Padronização e Estoque.']::text[]),
(151, 'Intermediário', 'Qual é o método de 4 etapas que usamos para lavar utensílios e equipamentos?', 'Limpar, Lavar, Enxaguar e Sanitizar.', array['Molhar, Ensaboar, Escovar e Secar.', 'Raspar, Lavar, Secar com pano e Guardar.', 'Limpar, Desengordurar, Enxaguar e Polir.']::text[]),
(152, 'Intermediário', 'Qual a velocidade de extração dos sorvetes?', 'De 5 a 7,5 oz em 10 segundos.', array['De 3 a 5 oz em 10 segundos.', 'De 8 a 10 oz em 10 segundos.', 'De 5 a 7,5 oz em 15 segundos.']::text[]),
(153, 'Intermediário', 'Qual deve ser a proporção correta de suco concentrado e água?', '3 partes de suco para 15 de água.', array['1 parte de suco para 5,2 de água.', '2 partes de suco para 10 de água.', '3 partes de suco para 12 de água.']::text[]),
(154, 'Intermediário', 'Qual a ordem correta de experimentação dos refrigerantes?', 'Coca, Fanta, Coca Zero, Sprite Zero, Fanta Guaraná.', array['Coca Zero, Sprite Zero, Coca, Fanta, Fanta Guaraná.', 'Sprite Zero, Fanta Guaraná, Fanta, Coca, Coca Zero.', 'Coca, Coca Zero, Fanta, Fanta Guaraná, Sprite Zero.']::text[]),
(155, 'Intermediário', 'Qual a ordem de experimentação dos sucos?', 'Laranja e uva.', array['Uva e laranja.', 'Maracujá, laranja e uva.', 'Uva, maçã e laranja.']::text[]),
(156, 'Intermediário', 'Qual a temperatura do banho-maria e das coberturas?', 'De 57° a 63°C e de 46° a 52°C, respectivamente.', array['De 46° a 52°C e de 57° a 63°C, respectivamente.', 'De 49° a 57°C e de 40° a 45°C, respectivamente.', 'De 65° a 72°C e de 50° a 58°C, respectivamente.']::text[]),
(157, 'Intermediário', 'Quantas pedras de gelo colocamos nos refrigerantes P, M e G?', '0,5 pá (5 pedras), 2/3 pá (7 pedras) e 1 pá (10 pedras), respectivamente.', array['1/3 pá (3 pedras), 0,5 pá (5 pedras) e 2/3 pá (7 pedras).', '0,5 pá (6 pedras), 1 pá (10 pedras) e 1,5 pá (15 pedras).', '4 pedras no P, 8 pedras no M e 12 pedras no G.']::text[]),
(158, 'Intermediário', 'Quais as quantidades corretas de 1 Sundae?', '4 voltas e meia de massa (4,5 oz), 2 tiros de cobertura (1 oz) e 7 gramas de amendoim.', array['6 voltas de massa (6 oz), 2 tiros de cobertura (1 oz) e 14 g de amendoim.', '3 voltas e meia de massa (3,5 oz), 1 tiro de cobertura e 7 g de amendoim.', '4 voltas e meia de massa (4,5 oz), 1 tiro de cobertura e 10 g de amendoim.']::text[]),
(159, 'Intermediário', 'Quais as quantidades corretas de 1 Top Sundae?', '6 voltas de massa (6 oz), 2 tiros de cobertura (1 no fundo e 1 em cima = 1 oz), 1 tiro de paçoca (1 oz) e 2 bijus.', array['4,5 voltas de massa (4,5 oz), 2 tiros de cobertura, 7 g de amendoim e 1 biju.', '6 voltas de massa (6 oz), 3 tiros de cobertura, 2 tiros de paçoca e 1 biju.', '5 voltas de massa (5 oz), 2 tiros de cobertura, 20 g de paçoca e 2 bijus.']::text[]),
(160, 'Intermediário', 'Qual a temperatura ambiente do salão?', 'De 23 a 27°C.', array['De 18 a 22°C.', 'De 20 a 24°C.', 'De 25 a 30°C.']::text[]),
(161, 'Intermediário', 'Quais os materiais necessários que devemos ter no salão para limpeza das mesas e bancos?', '1 pano seco e 1 úmido para mesas, 1 pano seco e 1 úmido para bancos e 1 borrifador com sanitizante.', array['1 pano úmido único para mesas e bancos e 1 borrifador com detergente.', '2 panos secos para mesas, 1 pano para o chão e álcool 70%.', '3 panos úmidos e 1 balde com água e sabão.']::text[]),
(162, 'Intermediário', 'Quais são os 4 grupos de produtos que compõem o pedido do cliente?', 'Sanduíches, acompanhamentos, bebidas e sobremesas.', array['Hambúrgueres, frango, saladas e café.', 'Pães, carnes, molhos e embalagens.', 'Combos, avulsos, adicionais e brinquedos.']::text[]),
(163, 'Avançado', 'Qual a temperatura da tostadeira?', 'Placa A e B 271°C e Placa C 254°C.', array['Placa A e B 254°C e Placa C 271°C.', 'Placa A, B e C todas a 260°C.', 'Placa A e B 218°C e Placa C 177°C.']::text[]),
(164, 'Avançado', 'O que é contaminação cruzada?', 'É a transferência de microrganismos de um lugar para outro.', array['É a multiplicação de bactérias na zona de perigo térmico.', 'É a queima excessiva do óleo de fritura acima de 24%.', 'É a reação alérgica causada por glúten ou derivados do leite.']::text[]),
(165, 'Avançado', 'O que são Alérgenos?', 'São substâncias que podem causar reações alérgicas no organismo como resposta do sistema imunológico.', array['São bactérias que se multiplicam entre 4,4°C e 60°C.', 'São resíduos químicos de detergente ou sanitizante.', 'São compostos polares formados pela degradação da gordura.']::text[]),
(166, 'Avançado', 'Qual a calibragem do dispensador de ketchup?', 'Ketchup Regular 6 tiros = 2 oz/60 ml, Quarteirão 6 tiros = 3 oz/90 ml.', array['Ketchup Regular 4 tiros = 2 oz/60 ml, Quarteirão 4 tiros = 3 oz/90 ml.', 'Ketchup Regular 6 tiros = 3 oz/90 ml, Quarteirão 6 tiros = 2 oz/60 ml.', 'Ketchup Regular 10 tiros = 1 oz/30 ml, Quarteirão 6 tiros = 2 oz/60 ml.']::text[]),
(167, 'Avançado', 'Qual a calibragem do dispensador de mostarda?', '47 tiros = 1 oz/30 ml.', array['40 tiros = 1 oz/30 ml.', '30 tiros = 1 oz/30 ml.', '47 tiros = 2 oz/60 ml.']::text[]),
(168, 'Avançado', 'Qual a calibragem da pistola de molho Big Mac?', '4 tiros de 1/2 oz = 2 oz/60 ml.', array['6 tiros de 1/2 oz = 3 oz/90 ml.', '4 tiros de 1 oz = 4 oz/120 ml.', '2 tiros de 1/2 oz = 1 oz/30 ml.']::text[]),
(169, 'Avançado', 'Qual a velocidade do motor da tostadeira?', 'A partir de 3300.', array['A partir de 2500.', 'A partir de 1800.', 'A partir de 4200.']::text[]),
(170, 'Avançado', 'Qual o procedimento correto de sanitização dos tomates?', '1. Retirar pela tabela chart; 2. Lavar em água corrente; 3. Cobrir com sanitizante por 15 min; 4. Enxaguar em água corrente.', array['1. Retirar 1 caixa; 2. Cobrir com sanitizante por 10 min; 3. Fatiar sem enxaguar; 4. Guardar.', '1. Lavar com sabonete bactericida; 2. Deixar no cloro por 30 min; 3. Secar com pano; 4. Cortar.', '1. Retirar pelo chart; 2. Deixar no sanitizante por 5 min; 3. Ambientar por 4h; 4. Lavar após fatiar.']::text[]),
(171, 'Avançado', 'Qual procedimento devemos seguir ao trabalhar com a tela LOOK & COOK?', 'OSA: Olha, Serve e Ativa.', array['PEPS: Primeiro que Entra, Primeiro que Sai.', 'DFS: Medir, Calibrar e Registrar.', 'KVS: Iniciar, Condimentar e Embrulhar.']::text[]),
(172, 'Avançado', 'Qual o ponto de partida para as carnes vermelhas?', '10:1 a partir de 39" (Next Gen 41") | 4:1 a partir de 104" (Next Gen 126").', array['10:1 a partir de 45" (Next Gen 50") | 4:1 a partir de 90" (Next Gen 110").', '10:1 a partir de 30" (Next Gen 35") | 4:1 a partir de 120" (Next Gen 140").', '10:1 a partir de 42" (Next Gen 39") | 4:1 a partir de 126" (Next Gen 104").']::text[]),
(173, 'Avançado', 'Qual o Gap correto para as carnes de 10:1?', '225" por 20 segundos, final 290".', array['290" por 20 segundos, final 225".', '250" por 15 segundos, final 310".', '450" por 20 segundos, final 290".']::text[]),
(174, 'Avançado', 'Qual a temperatura da estufa de tortas?', 'De 66 a 82°C.', array['De 49 a 57°C.', 'De 79 a 85°C.', 'De 57 a 63°C.']::text[]),
(175, 'Avançado', 'Qual a capacidade máxima de tortas na estufa?', '32 tortas.', array['16 tortas.', '24 tortas.', '40 tortas.']::text[]),
(176, 'Avançado', 'O que significa Manutenção e Recuperação na área de produtos fritos?', 'Manutenção: ativar para manter o nível PLS. Recuperação: ativar para repor o nível PLS com gavetas zeradas.', array['Manutenção: limpar e filtrar a fritadeira. Recuperação: trocar o óleo aos 24%.', 'Manutenção: fritar metade do cesto. Recuperação: fritar o dobro da rodada máxima.', 'Manutenção: manter carnes na UHC por 60 min. Recuperação: voltar carnes frias ao óleo.']::text[]),
(177, 'Avançado', 'Qual a concentração correta de cloro no sanitizante presente nos panos e borrifadores?', 'De 50 a 100 ppm.', array['De 100 a 200 ppm.', 'De 25 a 50 ppm.', 'De 150 a 250 ppm.']::text[]),
(178, 'Avançado', 'Qual o rendimento da mostarda pouch?', '1235 sanduíches por kg.', array['950 sanduíches por kg.', '1500 sanduíches por kg.', '840 sanduíches por kg.']::text[]),
(179, 'Avançado', 'Qual o rendimento da Alface?', '45,4 sanduíches por kg.', array['35,2 sanduíches por kg.', '60,5 sanduíches por kg.', '28,4 sanduíches por kg.']::text[]),
(180, 'Avançado', 'Qual o tempo de vida primário dos sucos?', 'Uva 180 dias e Laranja 150 dias.', array['Uva 150 dias e Laranja 180 dias.', 'Uva 90 dias e Laranja 90 dias.', 'Uva 120 dias e Laranja 100 dias.']::text[]),
(181, 'Avançado', 'Quais são as três dimensões que concretizam a Missão do Embaixador na Experiência do Cliente?', 'Viagem do cliente, Experiência Familiar e Construção de Vendas.', array['Fazer bem, Fazer rápido e Fazer especial.', 'Qualidade, Serviço e Limpeza.', 'Sugestão de Vendas, Venda Sugestiva e Adicionais.']::text[]),
(182, 'Avançado', 'Em que ano e onde foi fundado o McDonald''s?', 'Em 1955, na cidade de Des Plaines, Illinois, Estados Unidos.', array['Em 1948, na cidade de Chicago, Califórnia, EUA.', 'Em 1961, na cidade de Nova York, EUA.', 'Em 1952, na cidade de Los Angeles, EUA.']::text[]),
(183, 'Avançado', 'Onde e em que ano inaugurou o primeiro McDonald''s no Brasil?', 'Em 1979, na rua Hilário de Gouveia, em Copacabana, no Rio de Janeiro.', array['Em 1981, na Avenida Paulista, em São Paulo.', 'Em 1975, em Ipanema, no Rio de Janeiro.', 'Em 1983, no Centro de São Paulo.']::text[]),
(184, 'Avançado', 'Quando inaugurou o primeiro McDonald''s em São Paulo?', 'Em 1981, na Av. Paulista.', array['Em 1979, na Av. Brigadeiro Faria Lima.', 'Em 1985, na Rua Augusta.', 'Em 1978, no Shopping Ibirapuera.']::text[]),
(185, 'Avançado', 'Qual a condimentação e quantidades de ingredientes do Big Mac?', '1 tiro de 1/2 oz de molho Big na base e no club, 12 g de alface na base e 12 g no club (24 g), 2 picles no club, 1 queijo na base e 2 carnes 10:1 com 3,5 g de cebola.', array['1 tiro de 1 oz de molho Big na base e no club, 14 g de alface na base e no club (28 g), 2 picles, 2 queijos e 2 carnes 10:1.', '1 tiro de 1/2 oz de molho Big na base e coroa, 24 g de alface na base, 1 picles, 1 queijo e 2 carnes 10:1.', '2 tiros de 1/2 oz de molho Big na base, 12 g de alface no club, 4 picles, 2 queijos e 2 carnes 10:1.']::text[]),
(186, 'Avançado', 'Qual a condimentação e quantidades de ingredientes do Big Tasty?', '2 tiros de 1 oz molho Tasty (base e coroa), 10 g cebola, 28 g alface, 2 tomates, 3 queijos ementhal, carne 4:1 (1, 2 ou 3) destacando a TAG.', array['1 tiro de 1/2 oz molho Tasty (base e coroa), 7 g cebola, 24 g alface, 2 tomates, 2 queijos cheddar, carne 4:1.', '2 tiros de 2/3 oz molho Tasty, 14 g cebola, 28 g alface, 3 tomates, 3 queijos cheddar e carne 10:1.', '1 tiro de 1 oz molho Tasty apenas na coroa, 7 g cebola, 28 g alface, 1 tomate, 2 queijos ementhal e 1 carne 4:1.']::text[]),
(187, 'Avançado', 'Quais são os 7 conceitos da UHC?', 'UHC é o coração da cozinha; Ativar pouco, porém sempre; Usar sistema de garagem; Conhecer tempos das carnes; Acelerar/desacelerar na mesma chamada; Seguir níveis PLS; Não compensar um erro com outro.', array['UHC a 90°C; Ativar lotes máximos sempre; Empilhar 4 carnes 4:1; Desligar timers no rush; Ignorar PLS; Misturar gavetas; Usar 1 gaveta.', 'Plano de chão; Rota Gerencial; Pré-Plantão; Pós-Plantão; Posicionamento; Checklist; Experimentação.', 'Limpar; Lavar; Enxaguar; Sanitizar; Secar ao ar; Etiquetar com 24h; Guardar na câmara.']::text[]),
(188, 'Avançado', 'O que é e para que serve a caramelização dos pães?', 'É a queima de 5% do açúcar do pão e serve para criar uma película que impede que os condimentos penetrem no pão.', array['É a queima de 15% do amido do pão para deixá-lo crocante por fora e seco por dentro.', 'É o aquecimento a 180°C por 10 segundos apenas para derreter o gergelim da coroa.', 'É a perda de 20% da umidade do pão na mesa para absorver melhor os molhos.']::text[]),
(189, 'Avançado', 'Quais são as temperaturas da Zona de Risco para crescimento de microrganismos?', 'De 4,4°C a 60°C.', array['De 1°C a 49°C.', 'De 10°C a 70°C.', 'De 0°C a 45°C.']::text[]),
(190, 'Avançado', 'Qual a temperatura de extração do sorvete?', '-8 a -9°C.', array['-4 a -6°C.', '-12 a -15°C.', '-1 a -4°C.']::text[]),
(191, 'Avançado', 'Qual a proporção correta de água e xarope para refrigerantes normais?', '1 parte de xarope para 5,2 partes de água.', array['3 partes de xarope para 15 partes de água.', '1 parte de xarope para 4,0 partes de água.', '2 partes de xarope para 6,5 partes de água.']::text[]),
(192, 'Avançado', 'Quais são os 7 básicos operacionais?', 'Plano de chão, Rota Gerencial, Pré-Plantão, Pós-Plantão, Posicionamento, Checklist e Experimentação.', array['Agilidade, Generosidade, Humildade, Vocação de Serviço, Inclusão, Simpatia e Vendas.', 'Chapa, Linha, Fritura, Bebidas, Sobremesas, Balcão e Drive-Thru.', 'Limpeza, Organização, Preparação, Estocagem, Recebimento, Contagem e Fechamento.']::text[]),
(193, 'Avançado', 'O que é overrun do mix e qual o seu percentual?', 'Mede a proporção entre mix e ar; seu percentual é de 55 a 65% com ideal 58%.', array['Mede o tempo de congelamento do cilindro; percentual de 40 a 50% com ideal 45%.', 'Mede a gordura do leite no mix; percentual de 20 a 30% com ideal 24%.', 'Mede a velocidade de extração em 10s; percentual de 70 a 80% com ideal 75%.']::text[]),
(194, 'Avançado', 'Quais as quantidades corretas de complementos dos sorvetes?', 'Gotas 50 g, Rocks 20 g, Ovomaltine 20 g, Paçoca 20 g, Ovo Shake 54 g.', array['Gotas 30 g, Rocks 30 g, Ovomaltine 30 g, Paçoca 15 g, Ovo Shake 40 g.', 'Gotas 20 g, Rocks 50 g, Ovomaltine 54 g, Paçoca 20 g, Ovo Shake 20 g.', 'Gotas 40 g, Rocks 15 g, Ovomaltine 25 g, Paçoca 25 g, Ovo Shake 60 g.']::text[]),
(195, 'Avançado', 'Qual a temperatura do café coado?', 'A partir de 77°C.', array['A partir de 65°C.', 'De 57° a 63°C.', 'A partir de 85°C.']::text[]),
(196, 'Avançado', 'Qual a proporção correta de água e café para o café coado?', '1.100 ml de água para 1 pacote de 50 g de café.', array['1.000 ml de água para 1 pacote de 100 g de café.', '1.500 ml de água para 1 pacote de 50 g de café.', '800 ml de água para 1 pacote de 40 g de café.']::text[]),
(197, 'Avançado', 'O que é Best Burger?', 'É o novo padrão para os hambúrgueres McDonald''s. Pequenas mudanças, grande impacto.', array['É o sistema de fritura rápida para carnes brancas em 3 minutos.', 'É o programa de auditoria semestral de limpeza das chapas.', 'É a campanha promocional exclusiva para venda no Drive-Thru.']::text[]),
(198, 'Avançado', 'Quais são as técnicas dos influencers vendedores?', 'Somos Especialistas, Gostamos de Surpreender, Criamos Oportunidades, Vivenciamos as mesmas coisas, Criamos tendência, Somos Afetuosos.', array['Sugestão de Vendas, Venda Sugestiva, Adicionais, Combo Grande, Sobremesa e Café.', 'Fazer bem, Fazer rápido, Fazer especial, Sorrir, Agradecer e Despedir.', 'Olhar nos olhos, Oferecer bacon, Oferecer batata grande, Cobrar rápido e Entregar.']::text[]),
(199, 'Avançado', 'Qual o rendimento da batata?', '9,11 batatas pequenas por kg.', array['7,50 batatas pequenas por kg.', '12,40 batatas pequenas por kg.', '6,80 batatas pequenas por kg.']::text[]),
(200, 'Avançado', 'Qual a descrição do padrão ouro de qualidade do suco?', 'Frio, cor brilhante e sabor doce.', array['Com espuma, cor escura e sabor cítrico ácido.', 'Em temperatura ambiente, translúcido e sem açúcar.', 'Congelado com cristais de gelo e altamente concentrado.']::text[])
